function nodeDetail(k){var s=state.base.summary||{},src=state.plus.sources||[],rows='',title='',desc='';if(k==='sources'){title='Sources & priority';desc='CSV priority 100 enters planning before SocialMarket priority 50, while validation and dedupe remain mandatory.';rows=src.map(function(x){return'<div class="detailmini"><b>'+esc(x.display_name)+'</b><small>priority '+n(x.priority)+' · '+n(x.content_rows)+' rows · '+n(x.ready_rows)+' ready</small></div>'}).join('')}else if(k==='creative'){title='SEO + Creative Intelligence';desc='Imported content can be polished and scored once per batch; source facts are preserved and unsupported claims are not invented.';rows='<div class="detailmini"><b>AI</b><small>'+(state.plus.ai&&state.plus.ai.configured?'configured · '+esc(state.plus.ai.model):'not reported')+'</small></div><div class="detailmini"><b>Posters</b><small>'+state.assets.length+' uploaded image creatives</small></div><div class="detailmini"><b>Canva</b><small>workspace created; production Connect OAuth still required</small></div>'}else if(k==='schedule'){title='Conversion slot optimizer';desc='New jobs are assigned collision-safe Europe/Athens slots. Historical clicks/shares/saves/reach/views influence the score when enough evidence exists; otherwise system priors are used.';rows='<div class="detailmini"><b>Policy</b><small>conversion-learning-v3</small></div><div class="detailmini"><b>Human override</b><small>supported through manual schedule lock</small></div><div class="detailmini"><b>Learning</b><small>'+n(s.metric_rows)+' metric rows currently available</small></div>'}else if(k==='router'){title='Provider fabric';desc='Only verified account/platform routes with positive health score are executable.';rows=['facebook','instagram','tiktok','linkedin'].map(function(p){var x=topProvider(p);return'<div class="detailmini"><b>'+p+'</b><small>'+(x?esc(x.provider_key)+' · score '+Math.round(n(x.total_score)):'no safe route')+'</small></div>'}).join('')}else if(k==='publish'){title='Publisher execution';desc='Provider-specific executors claim only jobs assigned to them, preventing duplicate cross-provider claims.';rows='<div class="detailmini"><b>Approved</b><small>'+n(s.approved_jobs)+' waiting</small></div><div class="detailmini"><b>Scheduled</b><small>'+n(s.scheduled_jobs)+' accepted</small></div><div class="detailmini"><b>Published</b><small>'+n(s.published_jobs)+' confirmed</small></div>'}else if(k==='recovery'){title='Self-healing recovery';desc='Failed jobs are classified and retried or rerouted only when another verified safe route exists.';rows=recentRecovery().slice(0,3).map(function(x){return'<div class="detailmini"><b>'+esc(x.action)+'</b><small>'+esc(x.platform)+' · '+esc(x.old_provider||'—')+' → '+esc(x.new_provider||'—')+'</small></div>'}).join('')||'<div class="detailmini"><b>No recent recovery</b><small>Autopilot checks failures every 5 minutes.</small></div>'}else{title='Feedback learning';desc='Only observed metrics are used. The dashboard never invents conversion or revenue.';rows='<div class="detailmini"><b>Coverage</b><small>'+metricsCoverage()+'% of published count has metric rows</small></div><div class="detailmini"><b>Optimization</b><small>clicks, shares, saves and comments receive stronger scheduling weight</small></div><div class="detailmini"><b>Loop</b><small>results feed future provider and timing choices</small></div>'}return'<div class="detailbox"><h3>'+esc(title)+'</h3><div class="muted">'+esc(desc)+'</div><div class="detailcols">'+rows+'</div></div>'}
